import{_ as a,o as d,c as r,a2 as e}from"./chunks/framework.CqpfiAoK.js";const q=JSON.parse('{"title":"سطح گزرنے کے اصول","description":"","frontmatter":{},"headers":[],"relativePath":"ur/81-位面穿梭规则.md","filePath":"ur/81-位面穿梭规则.md"}'),o={name:"ur/81-位面穿梭规则.md"};function l(i,t,h,u,n,s){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="سطح-گزرنے-کے-اصول" tabindex="-1">سطح گزرنے کے اصول <a class="header-anchor" href="#سطح-گزرنے-کے-اصول" aria-label="Permalink to &quot;سطح گزرنے کے اصول&quot;">​</a></h1><table tabindex="0"><thead><tr><th>آئٹم</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>81</td></tr><tr><td>ماڈیول</td><td>بین السطح تعامل اور وقت کے اصول</td></tr><tr><td>بنیادی کلیدی الفاظ</td><td>سطح گزر، گزر کی اجازت، توانائی کی حد، اینکر انضمام، آلودگی کی روک تھام</td></tr></tbody></table><h2 id="_1-گزر-کے-عمل-کی-قانونی-حیثیت" tabindex="-1">1. گزر کے عمل کی قانونی حیثیت <a class="header-anchor" href="#_1-گزر-کے-عمل-کی-قانونی-حیثیت" aria-label="Permalink to &quot;1. گزر کے عمل کی قانونی حیثیت&quot;">​</a></h2><p>سطح گزر سے مراد جاندار فرد یا گروہ کی تکنیکی ذرائع یا سادھک صلاحیتوں کے ذریعے، ایک سطح سے دوسری سطح میں داخل ہونے کے لیے قانون کی رکاوٹ کو عبور کرنا ہے۔ اینکر سمبیوسس تہذیب کے قانونی فریم ورک کے تحت، سطح گزر &quot;اعلیٰ خطرے والا خاص عمل&quot; کے زمرے میں آتا ہے اور اسے سخت اجازت کے انتظام اور عمل کی نگرانی کے تابع ہونا چاہیے۔ &quot;سمبیوسس آئین&quot; کے آرٹیکل 47 میں واضح طور پر کہا گیا ہے: &quot;کوئی بھی تنظیم اور فرد بغیر اجازت کے خود مختار طور پر بین السطح گزر نہیں کر سکتا، اور نہ ہی سطح گزر کو دوسری سطح کی تہذیب کے خلاف لوٹ مار، مداخلت یا آلودگی کی سرگرمیوں کے لیے استعمال کر سکتا ہے۔&quot;</p><p>سطح گزر کو سخت کنٹرول کیوں کرنے کی ضرورت ہے، اس کی بنیادی وجہ یہ ہے کہ گزر کا عمل خود ہدف سطح پر متعدد اثرات مرتب کر سکتا ہے: قانون کی خلل، توانائی کا انجیکشن، شعور کی آلودگی، مائکروبیل حملہ اور ثقافتی مداخلت وغیرہ۔ یہ اثرات ہلکے درجے میں ہدف سطح میں مقامی غیر معمولیات کا باعث بنتے ہیں، سنگین درجے میں اس کی تہذیب کے ارتقاء کی راہ کو بدل سکتے ہیں، یہاں تک کہ قانون کے خاتمے کا باعث بن سکتے ہیں۔ لہذا، گزر کے اصولوں کا بنیادی مقصد &quot;گزر کے عمل کے بیرونی اثرات کو قابل قبول حد تک کنٹرول کرنا&quot; ہے۔</p><h2 id="_2-گزر-کی-اجازت-کی-درجہ-بندی-کا-نظام" tabindex="-1">2. گزر کی اجازت کی درجہ بندی کا نظام <a class="header-anchor" href="#_2-گزر-کی-اجازت-کی-درجہ-بندی-کا-نظام" aria-label="Permalink to &quot;2. گزر کی اجازت کی درجہ بندی کا نظام&quot;">​</a></h2><p>ہینگ یوان ژو سطح گزر کی اجازت کی درجہ بندی کا نظام نافذ کرتا ہے، گزر کے مقصد، ہدف سطح کی قسم اور گزرنے والے کی قابلیت کے مطابق اجازت کو چار درجوں میں تقسیم کرتا ہے:</p><table tabindex="0"><thead><tr><th>اجازت کی سطح</th><th>قابل اطلاق منظرنامہ</th><th>منظوری دینے والا ادارہ</th><th>درستگی کا دور</th><th>اضافی شرائط</th></tr></thead><tbody><tr><td>A سطح (آثار قدیمہ کا مشاہدہ)</td><td>خالص مشاہداتی آثار قدیمہ، کوئی جسمانی رابطہ نہیں</td><td>سطح انتظامیہ بیورو</td><td>واحد کام</td><td>کاپی آئینہ + الگ تھلگ جگہ کا اسکیم استعمال کرنا ضروری ہے</td></tr><tr><td>B سطح (تعلیمی تبادلہ)</td><td>ہدف سطح کی تہذیب کے ساتھ محدود علمی تبادلہ</td><td>سطح انتظامیہ بیورو + ثقافت کی وزارت</td><td>زیادہ سے زیادہ ایک سال</td><td>باہمی عدم مداخلت کا معاہدہ دستخط کرنا ضروری ہے</td></tr><tr><td>C سطح (وسائل کا تعاون)</td><td>مساوات اور باہمی فائدے کی بنیاد پر وسائل اور ٹیکنالوجی کا تعاون</td><td>اینکر کونسل کی خصوصی منظوری</td><td>زیادہ سے زیادہ تین سال</td><td>ہدف سطح کی تہذیب کی رضامندی حاصل کرنی ضروری ہے</td></tr><tr><td>D سطح (ہنگامی مداخلت)</td><td>جب ہدف سطح کو ناپید ہونے کے درجے کا بحران درپیش ہو تو انسانی مداخلت</td><td>اینکر کونسل کی ہنگامی قرارداد</td><td>بحران کے دوران</td><td>بعد میں مکمل مداخلت کی رپورٹ جمع کروانی ضروری ہے</td></tr></tbody></table><p>کسی بھی سطح کی گزر کی اجازت میں درج ذیل اعمال ممنوع ہیں: ہدف سطح کی اصل توانائی کو لوٹنا، اپنی سطح کی نظریے کو زبردست پھیلانا، رضامندی کے بغیر جینیاتی یا شعور کی تبدیلی کرنا، ہدف سطح میں مستقل فوجی اڈے قائم کرنا، اور کسی بھی شکل میں نوآبادیاتی تسلط۔</p><h2 id="_3-گزر-کی-تکنیکی-ضروریات-اور-توانائی-کی-حد" tabindex="-1">3. گزر کی تکنیکی ضروریات اور توانائی کی حد <a class="header-anchor" href="#_3-گزر-کی-تکنیکی-ضروریات-اور-توانائی-کی-حد" aria-label="Permalink to &quot;3. گزر کی تکنیکی ضروریات اور توانائی کی حد&quot;">​</a></h2><p>سطح گزر کے لیے سخت تکنیکی شرائط کی تکمیل کی ضرورت ہوتی ہے۔ سب سے پہلے، گزرنے والے کے پاس &quot;جگہ قانونی ضابطے کے نظام&quot; کا تیسرا مرحلہ (خلا کی تبدیلی) یا اس سے زیادہ سادھک ہونا چاہیے، یا معیار کے مطابق سطح گزر کی گاڑی لے جانا چاہیے۔ دوسرا، گزر کے نقطہ آغاز اور اختتام دونوں جگہوں پر اینکر کے ذریعے نقاط کا انضمام ہونا ضروری ہے، اینکر پوزیشننگ کے بغیر اندھا گزر کا عمل سخت ممنوع ہے۔</p><p>گزر کے عمل میں توانائی کی کھپت ہدف سطح کی قانونی رکاوٹ کی شدت کے براہ راست متناسب ہے۔ ہینگ یوان ژو نے معیاری &quot;گزر توانائی کی حد کی جدول&quot; قائم کی ہے، مختلف اقسام کی سطحوں کے گزر کے لیے درکار کم از کم توانائی درج ذیل ہے:</p><ul><li>مادہ بنیادی سطح: 1000 معیاری توانائی اکائیاں</li><li>توانائی ظاہر سطح: 5000 معیاری توانائی اکائیاں</li><li>شعور غالب سطح: 20000 معیاری توانائی اکائیاں</li><li>قانون ٹوٹا سطح: 50000 معیاری توانائی اکائیاں (اور کامیابی کی شرح 30% سے کم)</li><li>اصل قریبی سطح: نظریاتی قدر 100000 سے زیادہ، فی الحال کوئی کامیابی کا ریکارڈ نہیں</li></ul><p>گزر کی توانائی گزرنے والے یا گاڑی خود ہی لے جانا چاہیے، گزر کے عمل کے لیے ہدف سطح سے توانائی نکالنا ممنوع ہے۔ اس شرط کا مقصد یہ ہے کہ گزر کے عمل کی وجہ سے ہدف سطح پر توانائی کی لوٹ مار نہ ہو۔</p><h2 id="_4-گزر-کے-عمل-میں-آلودگی-کی-روک-تھام" tabindex="-1">4. گزر کے عمل میں آلودگی کی روک تھام <a class="header-anchor" href="#_4-گزر-کے-عمل-میں-آلودگی-کی-روک-تھام" aria-label="Permalink to &quot;4. گزر کے عمل میں آلودگی کی روک تھام&quot;">​</a></h2><p>سطح گزر کے سب سے بڑے خطرات میں سے ایک ہے &quot;بین السطح آلودگی&quot;، جس میں شامل ہیں حیاتیاتی آلودگی (اپنی سطح کے مائکروجنزم لے کر ہدف سطح میں داخل ہونا)، توانائی کی آلودگی (اپنی سطح کی توانائی کی باقیات کا ہدف سطح کے قانون میں خلل) اور شعور کی آلودگی (گزرنے والے کے شعور کے اتار چڑھاؤ کا ہدف سطح کے شعور کے ڈومین پر اثر)۔</p><p>آلودگی کی روک تھام کے لیے، تمام گزرنے والوں کو روانگی سے پہلے &quot;تین سطحی صاف کرنے کا پروگرام&quot; مکمل کرنا ضروری ہے:</p><ol><li><strong>حیاتیاتی صفائی</strong>: الگ تھلگ جگہ میں 72 گھنٹے تک مائکروبیل اسکریننگ اور خاتمہ کرنا، اس بات کو یقینی بنانا کہ وہ اپنی سطح کا کوئی پیتھوجین نہیں لے جا رہے</li><li><strong>توانائی کی صفائی</strong>: اینکر انضمام ڈیوائس کے ذریعے گزرنے والے کی توانائی کی فریکوئنسی کو ہدف سطح کے ساتھ ہم آہنگ حد میں ایڈجسٹ کرنا، توانائی کے رد عمل کو کم کرنا</li><li><strong>شعور کی صفائی</strong>: شعور کو بلاک کرنے کی تربیت دینا، اس بات کو یقینی بنانا کہ گزر کے عمل میں وہ فعال طور پر ایسی خواہش کے اتار چڑھاؤ نہیں چھوڑتے جو ہدف سطح کے شعور کے ڈومین میں خلل ڈال سکتے ہیں</li></ol><p>اس کے علاوہ، ہدف سطح میں گزرنے والے کی سرگرمیوں کا دائرہ سخت طور پر &quot;گزر کی اجازت سے مقررہ علاقے&quot; تک محدود ہے، غیر مجاز پھیلاؤ ممنوع ہے۔ اپنی سطح میں واپس آنے کے بعد، گزرنے والے کو دوبارہ الگ تھلگ مشاہدے سے گزرنا چاہیے، وقت کم از کم ہدف سطح کی وقت کی رفتار کے لحاظ سے تبدیل کردہ 30 دن۔</p><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>سطح گزر کے اصول بین السطح تعامل کی پہلی سلامتی کی دفاعی لکیر ہیں۔ وہ تین میکانزم کے ذریعے — اجازت کی درجہ بندی، تکنیکی رکاوٹیں اور آلودگی کی روک تھام — اس بات کو یقینی بناتے ہیں کہ گزر کا عمل ہمیشہ &quot;کم اثر، ٹریس کرنے کے قابل، جوابدہ&quot; راستے پر چلے۔ اصولوں کا حتمی مقصد تہذیبوں کے درمیان تبادلے کو محدود کرنا نہیں ہے، بلکہ تبادلے کو سمبیوسس کے طریقے سے ہونے دینا ہے، لوٹ مار کے طریقے سے نہیں۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>80-سطح کا نظریہ اور درجہ بندی</li><li>88-بین السطح اخلاقی رہنما خطوط</li><li>62-جگہ قانونی ٹیکنالوجی کا نفاذ</li></ul>',23)])])}const p=a(o,[["render",l]]);export{q as __pageData,p as default};
